{
  "recipe_id": "appam-03",
  "title": "Appam (lace-edged fermented rice hoppers)",
  "ingredients": [
    {
      "name": "Raw rice (pachari), soaked",
      "amount": "500g"
    },
    {
      "name": "Cooked rice",
      "amount": "100g"
    },
    {
      "name": "Fresh thick coconut milk",
      "amount": "400g"
    },
    {
      "name": "Fresh toddy (or 1g instant yeast + 10g sugar in warm water)",
      "amount": "100g"
    },
    {
      "name": "Sugar",
      "amount": "15g"
    },
    {
      "name": "Fine sea salt",
      "amount": "7g"
    }
  ],
  "method": "Soak the raw rice 4 hours, then grind with the cooked rice and half the\ncoconut milk to a completely smooth batter. Stir in the toddy (or the yeast\nmixture) and the sugar, and ferment 8 hours at room temperature until bubbly\nand risen. Just before cooking, stir in the remaining coconut milk and the 7g\nfine sea salt; the batter should coat a spoon thinly. Heat an appachatti,\npour in a small ladleful, and immediately lift and swirl the pan in one full\ncircle so the batter climbs the walls — this makes the crisp lace edge with\nthe soft, spongy centre. Cover and cook 2 minutes; the appam is done when the\nedges release and the centre springs back."
}

{
  "recipe_id": "thayir-04",
  "title": "Thayir — Homemade Curd (set overnight)",
  "ingredients": [
    {
      "name": "Whole milk (full-fat)",
      "amount": "1000g"
    },
    {
      "name": "Live curd from the previous batch",
      "amount": "30g"
    }
  ],
  "method": "Bring the milk just to a boil, then simmer 5 minutes to concentrate it\nslightly — this gives a thicker set. Cool to 40–43°C: the milk should feel\ndistinctly warm, not hot, on a clean fingertip held for ten seconds. Whisk\nthe starter curd until smooth, stir it through the milk, cover, and leave\ncompletely undisturbed for 6 to 8 hours at around 30°C. In cold weather, set\nthe pot inside a switched-off oven with the light on, or wrap it in a thick\ntowel next to a hot-water bottle. The curd is set when it jiggles as one mass\nand the surface releases a little clear whey. Refrigerate immediately once\nset; over-fermenting at room temperature turns it sharply sour by evening.\nSave 30g as the starter for tomorrow's batch."
}

{
  "recipe_id": "kadumanga-06",
  "title": "Kadumanga Achar (Kerala fermented tender mango pickle)",
  "ingredients": [
    {
      "name": "Tender baby mangoes (kannimanga), whole",
      "amount": "1000g"
    },
    {
      "name": "Crystal sea salt",
      "amount": "150g"
    },
    {
      "name": "Kashmiri chilli powder",
      "amount": "50g"
    },
    {
      "name": "Gingelly (sesame) oil",
      "amount": "60g"
    },
    {
      "name": "Mustard seeds",
      "amount": "10g"
    },
    {
      "name": "Fenugreek powder, roasted",
      "amount": "5g"
    },
    {
      "name": "Asafoetida (hing)",
      "amount": "3g"
    }
  ],
  "method": "Wipe the mangoes dry — no water must touch them at any stage. Layer them\nwith the crystal salt in a sterilised bharani (ceramic pickle jar), close,\nand shake once daily. Over 10 to 14 days the salt draws out the mango's own\nbrine and the fruit ferments in it, turning olive-drab and pleasantly tangy.\nThen heat the gingelly oil, crackle the mustard seeds, switch off the heat,\nand stir in the chilli powder, fenugreek powder and asafoetida. Cool the\nspiced oil completely and fold it through the mangoes and their brine.\nReturn everything to the bharani. The pickle is eatable in a week but\nmatures over a month; it keeps a year at room temperature if only dry\nspoons ever enter the jar."
}
